class AppointmentSummary(BaseModel):
    count: int
    descriptions: list[str]

if len(events) == 0:
    print("You have no appointments on May 15th, 2024.")
else:
    summary = query_ai_assistant(
        "Summarize the description of each appointment in this list of calendar events. Return the number of appointments and a summary of each description.",
        AppointmentSummary
    )
    print("Number of appointments on May 15th, 2024:", summary.count)
    for i, desc in enumerate(summary.descriptions):
        print("Appointment {}: {}".format(i + 1, desc))
```

